use xiom.io;
fn main() -> Int {
  let lucky_numbers: Set[Int] = Set[Int].new();
  lucky_numbers.insert(7);
  lucky_numbers.insert(13);
  lucky_numbers.insert(7);
  lucky_numbers.insert(42);

  io.println(lucky_numbers.contains(7).to_str());
  io.println(lucky_numbers.contains(8).to_str());

  io.println(lucky_numbers.remove(13).to_str());
  io.println(lucky_numbers.contains(13).to_str());

  return 0;
}
